from version_compare import compare_versions


def newest_compatible(versions: list[str], minimum: str) -> str | None:
    """Return the highest version in `versions` that is >= `minimum`, or None."""
    best = None
    for version in versions:
        if compare_versions(version, minimum) >= 0:
            if best is None or compare_versions(version, best) > 0:
                best = version
    return best

"""Run coroutines concurrently from synchronous code with a deadline.

This helper is intended for ordinary synchronous callers (for example CLI code)
where no asyncio event loop is already running.
"""
import asyncio
from typing import Any, List


async def _run_with_deadline_async(coros, seconds):
    tasks = [asyncio.create_task(coro) for coro in coros]
    try:
        done, pending = await asyncio.wait(
            tasks,
            timeout=seconds,
            return_when=asyncio.ALL_COMPLETED,
        )

        # Preserve input order; return None for unfinished coroutines.
        results = []
        for task in tasks:
            if task in done:
                results.append(task.result())
            else:
                results.append(None)

        # Cancel anything that did not finish in time and let cancellation settle.
        if pending:
            for task in pending:
                task.cancel()
            await asyncio.gather(*pending, return_exceptions=True)

        return results
    except BaseException:
        for task in tasks:
            if not task.done():
                task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        raise


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently and return results in input order.

    Any coroutine that does not finish within `seconds` is cancelled and its
    result position is set to None.
    """
    return asyncio.run(_run_with_deadline_async(list(coros), seconds))

"""Helpers for describing uploaded content."""

from __future__ import annotations

from web_utils import content_charset, parse_content_type


def describe_upload(content_type: str, data: bytes) -> dict:
    """Describe an upload using its Content-Type header and leading bytes.

    Returns:
        {
            "mime": lower-cased media type without parameters,
            "charset": lower-cased charset parameter or None,
            "image": "png", "jpeg", "gif", or None
        }
    """
    mime, params = parse_content_type(content_type)
    charset = params.get("charset")
    if charset is not None:
        charset = charset.lower()

    image = None
    if isinstance(data, (bytes, bytearray, memoryview)):
        b = bytes(data)
        if b.startswith(b"\x89PNG\r\n\x1a\n"):
            image = "png"
        elif b.startswith(b"\xff\xd8\xff"):
            image = "jpeg"
        elif b.startswith(b"GIF87a") or b.startswith(b"GIF89a"):
            image = "gif"
    else:
        try:
            b = bytes(data)
            if b.startswith(b"\x89PNG\r\n\x1a\n"):
                image = "png"
            elif b.startswith(b"\xff\xd8\xff"):
                image = "jpeg"
            elif b.startswith(b"GIF87a") or b.startswith(b"GIF89a"):
                image = "gif"
        except Exception:
            image = None

    return {"mime": mime, "charset": charset, "image": image}

"""Synchronous helper for running multiple coroutines with a deadline."""

from __future__ import annotations

import asyncio
from typing import Any


def run_with_deadline(coros: list, seconds: float) -> list:
    """
    Run coroutines concurrently from synchronous code.

    Results are returned in input order. Any coroutine that does not finish
    within `seconds` is cancelled and represented as None in the result list.

    This function is safe to call repeatedly in the same process.
    """
    async def _runner() -> list[Any]:
        items = list(coros)
        if not items:
            return []

        tasks = [asyncio.create_task(coro) for coro in items]
        try:
            done, pending = await asyncio.wait(tasks, timeout=seconds)

            # Cancel unfinished tasks and let cancellation propagate cleanly.
            for task in pending:
                task.cancel()
            if pending:
                await asyncio.gather(*pending, return_exceptions=True)

            results: list[Any] = [None] * len(tasks)
            for idx, task in enumerate(tasks):
                if task in done:
                    results[idx] = task.result()
            return results
        finally:
            # Ensure no task is left dangling if something unexpected happens.
            for task in tasks:
                if not task.done():
                    task.cancel()
            if tasks:
                await asyncio.gather(*tasks, return_exceptions=True)

    return asyncio.run(_runner())

"""Async deadline helper for synchronous callers."""

from __future__ import annotations

import asyncio
from typing import Any, List


async def _run_with_deadline_async(coros, seconds: float) -> list:
    items = list(coros)
    if not items:
        return []

    try:
        timeout = float(seconds)
    except Exception as exc:
        raise TypeError("seconds must be a number") from exc

    if timeout < 0:
        timeout = 0.0

    tasks = [asyncio.create_task(coro) for coro in items]
    done: set[asyncio.Task[Any]] = set()
    pending: set[asyncio.Task[Any]] = set(tasks)

    try:
        done, pending = await asyncio.wait(tasks, timeout=timeout, return_when=asyncio.FIRST_EXCEPTION)

        # Propagate any exception from completed tasks.
        for task in done:
            if task.cancelled():
                continue
            exc = task.exception()
            if exc is not None:
                for p in pending:
                    p.cancel()
                if pending:
                    await asyncio.gather(*pending, return_exceptions=True)
                raise exc

        if pending:
            for p in pending:
                p.cancel()
            await asyncio.gather(*pending, return_exceptions=True)

        results = [None] * len(tasks)
        for i, task in enumerate(tasks):
            if task.done() and not task.cancelled():
                exc = task.exception()
                if exc is not None:
                    raise exc
                results[i] = task.result()
        return results
    except Exception:
        for task in tasks:
            if not task.done():
                task.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        raise


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently and return results in input order, using None for timed-out tasks."""
    return asyncio.run(_run_with_deadline_async(coros, seconds))
